@Reducer
struct Counter {
  @ObservableState
  struct State: Equatable { var count = 0 }
  enum Action { case incrementButtonTapped }
  var body: some Reducer<State, Action> {
    Reduce { state, action in
      switch action {
      case .incrementButtonTapped: state.count += 1; return .none
      }
    }
  }
}
// view: let store: StoreOf<Counter>; Button("+") { store.send(.incrementButtonTapped) }

