@Observable final class FeedModel {
    private(set) var state: FeedState
    init(state: FeedState = FeedState()) { self.state = state }
    func send(_ intent: Intent) { state = reduce(state, intent) }
    private func reduce(_ s: FeedState, _ i: Intent) -> FeedState {
        switch i { case .refresh: return FeedState(items: s.items, loading: true) }
    }
}
